   562  otError BorderAgent::ForwardToLeader(const Coap::Message &   aMessage,
   563                                       const Ip6::MessageInfo &aMessageInfo,
   564                                       const char *            aPath,
   565                                       bool                    aPetition,
   566                                       bool                    aSeparate)
   567  {
   568      otError          error          = OT_ERROR_NONE;
   569      ForwardContext * forwardContext = NULL;
   570      Ip6::MessageInfo messageInfo;
   571      Coap::Message *  message = NULL;
   572      uint16_t         offset  = 0;
   573
   574      VerifyOrExit((message = NewMeshCoPMessage(Get<Coap::Coap>())) != NULL, error = OT_ERROR_NO_BUFS);
   575
   576      if (aSeparate)
   577      {
   578          SuccessOrExit(error = Get<Coap::CoapSecure>().SendAck(aMessage, aMessageInfo));
   579      }
   580
   581      forwardContext = static_cast<ForwardContext *>(GetInstance().HeapCAlloc(1, sizeof(ForwardContext)));
   582      VerifyOrExit(forwardContext != NULL, error = OT_ERROR_NO_BUFS);
   583
   584      forwardContext = new (forwardContext) ForwardContext(*this, aMessage, aPetition, aSeparate);
   585
   586      SuccessOrExit(error = message->Init(OT_COAP_TYPE_CONFIRMABLE, OT_COAP_CODE_POST, aPath));
   587
   588      // Payload of c/cg may be empty
   589      if (aMessage.GetLength() - aMessage.GetOffset() > 0)
   590      {
   591          SuccessOrExit(error = message->SetPayloadMarker());
   592      }
   593
   594      offset = message->GetLength();
   595      SuccessOrExit(error = message->SetLength(offset + aMessage.GetLength() - aMessage.GetOffset()));
   596      aMessage.CopyTo(aMessage.GetOffset(), offset, aMessage.GetLength() - aMessage.GetOffset(), *message);
   597
   598      SuccessOrExit(error = Get<Mle::MleRouter>().GetLeaderAloc(messageInfo.GetPeerAddr()));
   599      messageInfo.SetPeerPort(kCoapUdpPort);
   600      messageInfo.SetSockAddr(Get<Mle::MleRouter>().GetMeshLocal16());
   601      messageInfo.SetSockPort(kCoapUdpPort);
   602
   603      SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, messageInfo, HandleCoapResponse, forwardContext));
